SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.bond_type = '#' THEN b.molecule_id END) / COUNT(DISTINCT m.molecule_id) AS percent
FROM molecule m
LEFT JOIN bond b ON m.molecule_id = b.molecule_id;

SELECT (COUNT(CASE WHEN strftime('%Y', Date) = '2010' THEN 1 END) * 100.0 / COUNT(*)) - (COUNT(CASE WHEN strftime('%Y', Date) = '2011' THEN 1 END) * 100.0 / COUNT(*)) AS percentage_difference
FROM badges
WHERE Name = 'Students';

SELECT ROUND(AVG(CASE WHEN Admission = '+' THEN 100.0 ELSE 0 END), 2) AS inpatient_percentage
FROM Patient
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

SELECT 1.0 * COUNT(CASE WHEN Laboratory.GOT >= 60 AND Patient.Diagnosis = 'SLE' THEN Laboratory.ID END) / NULLIF(COUNT(CASE WHEN Laboratory.GOT >= 60 THEN Laboratory.ID END), 0) AS percentage
FROM Laboratory
JOIN Patient ON Laboratory.ID = Patient.ID;
